INSERT INTO repo_kcrs (kcr_id, name, domain, concept_category, concept_type, definition, scope, core_principles, semantic_description, keywords_synonyms, status) VALUES ('KCR_000901', 'energy and power', 'Engineering & Technology', 'Signals and Systems', 'Technical Concept', 'A signal measure based on the integral or average of squared magnitude, used to distinguish energy-type and power-type signals.', 'Applies to the analysis, design, implementation, interpretation, or evaluation of energy and power within Signals and Systems, particularly where the Signal Representation module establishes its technical context.', 'Core considerations include the defining characteristics of energy and power, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it.', 'A signal measure based on the integral or average of squared magnitude, used to distinguish energy-type and power-type signals. Within Signal Representation, the concept covers Applies to the analysis, design, implementation, interpretation, or evaluation of energy and power within Signals and Systems, particularly where the Signal Representation module establishes its technical context. Key technical considerations are Core considerations include the defining characteristics of energy and power, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it.', 'energy and power; Core considerations include the defining characteristics of energy and power, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it; Signals and Systems', 'Active'), ('KCR_000902', 'transformations', 'Engineering & Technology', 'Signals and Systems', 'Technical Concept', 'Operations that change a signal''s amplitude, time scale, shift, reversal, or other representation.', 'Applies to the analysis, design, implementation, interpretation, o